// Stretch (D36): a dispute evidence pack for one order. Everything in it comes from our own rows
// (the signed offer as issued, the order, the gate's decisions); nothing is generated by an LLM.
// The merchant signs the pack, so a reviewer holding the registry key can check that it wasn't
// edited after export, and each claim (offer signature, cart hash) is re-checked here, not assumed.
import { hash, signEnvelope, verifyEnvelope, type SignedEnvelope, type SignedOffer } from "@handshake/core";
import type { GateContext } from "../gate/verify.js";
import { toPayPalValue } from "../paypal/money.js";
import type { OfferStore } from "../offers/store.js";

export interface EvidenceDeps {
  gate: GateContext;
  offers: Pick<OfferStore, "getSignedOffer" | "getAgent">;
}

export interface EvidencePack {
  v: 1;
  type: "dispute_evidence";
  generatedAt: string;
  merchant: { merchantId: string; merchantAgentId: string; paypalMerchantId: string };
  order: {
    id: string;
    status: string;
    path: "passkey" | "mandate";
    totalMinor: number;
    currency: string;
    amount: string;
    createdAt: string;
    paypalOrderId: string | null;
    authorizationId: string | null;
    captureId: string | null;
    refundedMinor: number;
    trackingNumber: string | null;
  };
  /** The offer the buyer's agent accepted, with the merchant signature it was issued with. */
  offer: SignedOffer;
  checks: {
    /** hash(offer.payload) equals the hash the gate stored on the order. */
    offerHashMatchesOrder: boolean;
    /** The offer signature verifies under the merchant agent's registry key. */
    offerSignatureValid: boolean;
    /** The order total equals the signed offer total (both integer minor units). */
    totalMatchesOffer: boolean;
  };
  /** What the human approved: a passkey over this cart hash, or a mandate it fit inside. */
  approval: { kind: "passkey" | "mandate"; approvalHash: string; mandateId: string | null };
  decisions: { step: string; result: string; reason: string }[];
  /** Plain-language lines for the PayPal dispute notes field. */
  summary: string[];
}

export class EvidenceError extends Error {}

const iso = (ms: number) => new Date(ms).toISOString();

export async function buildEvidencePack(
  deps: EvidenceDeps,
  orderId: string,
  now: number = Date.now(),
): Promise<SignedEnvelope<EvidencePack>> {
  const { gate } = deps;
  const order = await gate.store.getOrder(orderId);
  if (!order) throw new EvidenceError("unknown order");
  const offer = await deps.offers.getSignedOffer(order.offerId);
  if (!offer) throw new EvidenceError("offer row missing");
  const agent = await deps.offers.getAgent(offer.kid);
  const decisions = (await gate.store.listDecisions(order.requestId)).map(({ step, result, reason }) => ({
    step,
    result,
    reason,
  }));

  const checks = {
    offerHashMatchesOrder: hash(offer.payload) === order.offerHash,
    offerSignatureValid:
      agent !== undefined &&
      agent.role === "merchant" &&
      agent.merchantId === gate.self.merchantId &&
      verifyEnvelope(offer, agent.publicKey, offer.kid, "offer"),
    totalMatchesOffer: offer.payload.totalMinor === order.totalMinor && offer.payload.currency === order.currency,
  };
  const amount = toPayPalValue(order.totalMinor);
  const approvalLine =
    order.path === "passkey"
      ? `The buyer approved this exact cart with a passkey (biometric) on their own device; the signed challenge was the cart hash ${order.approvalHash}.`
      : `The buyer pre-approved a spending mandate (signed with their passkey) and this cart fit inside its limits; mandate ${order.mandateId ?? "?"}, approval hash ${order.approvalHash}.`;
  const items = offer.payload.items.map((i) => `${i.qty} × ${i.sku} at ${toPayPalValue(i.unitMinor)}`).join(", ");
  const summary = [
    `Order ${order.id}, PayPal order ${order.paypalOrderId ?? "none"}, capture ${order.captureId ?? "none"}: ${amount} ${order.currency}.`,
    `Items, from the merchant-signed offer ${offer.payload.offerId}: ${items}.`,
    approvalLine,
    `Every gate check passed before money moved: ${
      decisions
        .filter((d) => d.result === "pass")
        .map((d) => d.step)
        .join(", ") || "none recorded"
    }.`,
    order.trackingNumber ? `Shipped with tracking number ${order.trackingNumber}.` : "No tracking number recorded.",
  ];

  const pack: EvidencePack = {
    v: 1,
    type: "dispute_evidence",
    generatedAt: iso(now),
    merchant: {
      merchantId: gate.self.merchantId,
      merchantAgentId: gate.self.merchantAgentId,
      paypalMerchantId: gate.self.paypalMerchantId,
    },
    order: {
      id: order.id,
      status: order.status,
      path: order.path,
      totalMinor: order.totalMinor,
      currency: order.currency,
      amount,
      createdAt: iso(order.createdAt),
      paypalOrderId: order.paypalOrderId,
      authorizationId: order.authorizationId,
      captureId: order.captureId,
      refundedMinor: order.refundedMinor,
      trackingNumber: order.trackingNumber,
    },
    offer,
    checks,
    approval: { kind: order.path, approvalHash: order.approvalHash, mandateId: order.mandateId },
    decisions,
    summary,
  };
  return signEnvelope(pack, gate.self.privateKey, gate.self.merchantAgentId);
}
